"""Collect and substitute ``@memory`` references in LLM-facing instruction prose.

Pure transform over a schema-scoped ``MemoryManager.read_all`` map (same
readable set as the ``### Memory:`` section). Train-time validation of token
legality lives elsewhere; this module only resolves what is already readable.
"""

from __future__ import annotations

import re
from typing import Mapping

import structlog

from rasa.mantle.memory.field import MemoryEntry
from rasa.mantle.prompts.memory_lines import PII_SET_PLACEHOLDER, render_memory_value

structlogger = structlog.get_logger()

# Matches ``@skill`` / ``@block`` token shapes: ``@memory.<namespace>.<entry>``.
# Boundaries keep the token whole: the lookbehind skips glued prefixes
# (``see@memory.project.card_id``), and the lookaheads reject a third segment so
# ``@memory.a.b.c`` is never substituted down to a value plus a dangling
# ``.c``. A trailing ``.`` that ends a sentence is still allowed.
_PROSE_MEMORY_REF_PATTERN = re.compile(
    r"(?<![\w])@memory\.([\w-]+)\.([\w-]+)(?![\w-])(?!\.[\w-])"
)
# Any ``@memory`` lookalike (bare, one-level, or longer); complete two-level
# forms are filtered out by :func:`collect_incomplete_prose_memory_tokens`.
# Segments require at least one ``[\w-]`` so a trailing ``.`` after a complete
# token is not swallowed into the lookalike.
_PROSE_MEMORY_LOOKALIKE_PATTERN = re.compile(r"(?<![\w])@memory(?:\.[\w-]+)*")


def collect_prose_memory_references(prose: str) -> list[str]:
    """Collect unique ``@memory.<namespace>.<entry>`` slot names from prose.

    Returns fully-qualified slot names (``project.foo``, ``card_select.bar``)
    in first-seen order. Only whole two-segment tokens count: longer paths
    (``@memory.a.b.c``) and tokens glued to preceding text are skipped here and
    reported by :func:`collect_incomplete_prose_memory_tokens` instead. Does not
    validate namespaces or readability — train validation and
    :func:`substitute_memory_prose_references` apply those rules.
    """
    seen: set[str] = set()
    referenced: list[str] = []
    for match in _PROSE_MEMORY_REF_PATTERN.finditer(prose):
        slot_name = f"{match.group(1)}.{match.group(2)}"
        if slot_name in seen:
            continue
        seen.add(slot_name)
        referenced.append(slot_name)
    return referenced


def collect_incomplete_prose_memory_tokens(prose: str) -> list[str]:
    """Collect unique incomplete ``@memory`` lookalikes from prose.

    Returns token strings (e.g. ``@memory.project``, ``@memory``,
    ``@memory.a.b.c``) in first-seen order. Well-formed
    ``@memory.<namespace>.<entry>`` tokens are excluded — those are handled by
    :func:`collect_prose_memory_references`.
    """
    seen: set[str] = set()
    incomplete: list[str] = []
    for match in _PROSE_MEMORY_LOOKALIKE_PATTERN.finditer(prose):
        token = match.group(0)
        if _PROSE_MEMORY_REF_PATTERN.fullmatch(token):
            continue
        if token in seen:
            continue
        seen.add(token)
        incomplete.append(token)
    return incomplete


def substitute_memory_prose_references(
    text: str,
    *,
    observing_skill_id: str,
    memory_entries: Mapping[str, MemoryEntry],
) -> str:
    """Replace ``@memory.<namespace>.<entry>`` tokens with live readable values.

    *memory_entries* must already be scoped for *observing_skill_id* (typically
    ``MemoryManager.read_all``). Missing keys are treated as denied; ``None``
    values as unset. In both cases the token is left unchanged and a WARNING
    is logged with ``reason`` ``denied`` or ``unset`` (token name only — never
    the value). Set PII fields become :data:`PII_SET_PLACEHOLDER`.
    """

    def _replace(match: re.Match[str]) -> str:
        token_name = match.group(0)
        slot_name = f"{match.group(1)}.{match.group(2)}"
        entry = memory_entries.get(slot_name)

        if entry is None:
            structlogger.warning(
                "mantle.prompts.memory_prose.unresolved",
                skill_id=observing_skill_id,
                token_name=token_name,
                reason="denied",
            )
            return token_name

        if entry.value is None:
            structlogger.warning(
                "mantle.prompts.memory_prose.unresolved",
                skill_id=observing_skill_id,
                token_name=token_name,
                reason="unset",
            )
            return token_name

        if entry.field.pii:
            structlogger.debug(
                "mantle.prompts.memory_prose.redacted",
                skill_id=observing_skill_id,
                token_name=token_name,
            )
            return PII_SET_PLACEHOLDER

        structlogger.debug(
            "mantle.prompts.memory_prose.substituted",
            skill_id=observing_skill_id,
            token_name=token_name,
        )
        return render_memory_value(entry.value)

    return _PROSE_MEMORY_REF_PATTERN.sub(_replace, text)
